  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium' });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto('file://' + path.resolve('index.html'));

  const closedByDefault = await page.locator('#delete-dialog').evaluate((d) => !d.open);
  const triggerClass = await page.locator('.trigger').evaluate((b) => b.classList.contains('trigger'));

  await page.locator('.trigger').click();
  await page.locator('#delete-dialog').waitFor({ state: 'visible' });
  const focused = await page.evaluate(() => document.activeElement?.textContent?.trim() || document.activeElement?.tagName);

  await page.addScriptTag({ content: axeSource });
  const axeResults = await page.evaluate(async () => await window.axe.run(document, { runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa'] } }));
  const violations = axeResults.violations.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) }));

  await page.getByRole('button', { name: 'Cancel' }).click();
  const restored = await page.evaluate(() => document.activeElement?.className);
  const stillClosed = await page.locator('#delete-dialog').evaluate((d) => !d.open);

  console.log(JSON.stringify({ closedByDefault, triggerClass, focused, restored, stillClosed, violations }, null, 2));
  await browser.close();

  if (!closedByDefault || !triggerClass || !stillClosed || violations.some(Boolean)) process.exit(1);
})();
